from pathlib import Path
lines = Path('values.yaml').read_text().splitlines()

def find_line(exact=None, contains=None, startswith=None):
    for i,l in enumerate(lines):
        if exact is not None and l == exact: return i
        if contains is not None and contains in l: return i
        if startswith is not None and l.startswith(startswith): return i
    return None

def dump(i, n=35, title=''):
    if i is None:
        print(f'MISSING {title}'); return
    print(f'\n##### {title} (line {i+1}) #####')
    for j in range(i, min(i+n, len(lines))):
        print(f'{j+1}:{lines[j]}')

# alertmanagerSpec
for i,l in enumerate(lines):
    if l == '  alertmanagerSpec:':
        dump(i, 80, 'alertmanager.alertmanagerSpec')
        break

# prometheusSpec - find retention and storageSpec within prometheus section
prom = find_line(exact='prometheus:')
# find prometheusSpec after prometheus:
for i in range(prom, len(lines)):
    if lines[i] == '  prometheusSpec:':
        dump(i, 120, 'prometheus.prometheusSpec (start)')
        break

# search retention / storageSpec / nodeSelector inside prometheusSpec
for i in range(prom, len(lines)):
    if lines[i].strip().startswith('retention:') and 'prometheusSpec' in '\n'.join(lines[max(0,i-50):i]):
        dump(i-2, 15, 'prometheus retention')
        break
for i,l in enumerate(lines):
    if l.strip() == 'storageSpec: {}' or (l.strip().startswith('storageSpec:') and i > prom):
        # only first after prometheusSpec
        if i > prom:
            dump(i-2, 40, 'prometheus storageSpec')
            break
for i,l in enumerate(lines):
    if i > prom and l == '    nodeSelector: {}':
        dump(i-2, 20, 'prometheusSpec.nodeSelector area')
        # also print nearby resources / tolerations / affinity
        break
for i,l in enumerate(lines):
    if 'serviceMonitorSelectorNilUsesHelmValues' in l:
        dump(i-1, 20, 'serviceMonitor selectors')
        break
for i,l in enumerate(lines):
    if i > prom and l.strip().startswith('scrapeInterval:'):
        dump(i-2, 15, 'scrapeInterval')
        break
for i,l in enumerate(lines):
    if i > prom and l.strip().startswith('resources:') and 'prometheusSpec' in '\n'.join(lines[max(0,i-200):i]):
        # first resources under prometheusSpec
        dump(i-2, 20, 'prometheusSpec.resources candidate')
        break

# grafana admin + ingress already known; find grafana nodeSelector passthrough
# In parent values, grafana chart values are nested under grafana:
g = find_line(exact='grafana:')
for i in range(g, g+350):
    if 'nodeSelector' in lines[i] or lines[i].startswith('  persistence:') or lines[i].strip() == 'persistence:':
        dump(i-1, 25, f'grafana vicinity {lines[i][:40]}')

# control plane
for key in ['kubeApiServer:','kubelet:','kubeControllerManager:','coreDns:','kubeEtcd:','kubeScheduler:','kubeProxy:','windowsMonitoring:','thanosRuler:','nodeExporter:','kubeStateMetrics:']:
    i = find_line(exact=key)
    dump(i, 8, key)

# defaultRules windows/etcd disable candidates
dump(find_line(exact='defaultRules:'), 40, 'defaultRules')
PY

